CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "WorkspaceRole" AS ENUM ('OWNER','ADMIN','EDITOR','VIEWER');
CREATE TYPE "ContentStatus" AS ENUM ('draft','ready','archived');
CREATE TYPE "ScheduleStatus" AS ENUM ('scheduled','cancelled','due','completed','failed');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email varchar(320) NOT NULL UNIQUE,password_hash varchar(255) NOT NULL,display_name varchar(120) NOT NULL,disabled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash char(64) NOT NULL UNIQUE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_expiry_idx ON sessions(user_id,expires_at);
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role "WorkspaceRole" NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT memberships_workspace_user_unique UNIQUE(workspace_id,user_id));
CREATE INDEX memberships_user_workspace_idx ON memberships(user_id,workspace_id);
CREATE TABLE content_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title varchar(180) NOT NULL,body text NOT NULL DEFAULT '',status "ContentStatus" NOT NULL DEFAULT 'draft',created_by_id uuid NOT NULL REFERENCES users(id),scheduled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX content_workspace_status_updated_idx ON content_items(workspace_id,status,updated_at DESC);
CREATE INDEX content_workspace_scheduled_idx ON content_items(workspace_id,scheduled_at);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,actor_id uuid REFERENCES users(id) ON DELETE SET NULL,action varchar(100) NOT NULL,target_type varchar(80) NOT NULL,target_id uuid,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_workspace_created_idx ON audit_events(workspace_id,created_at DESC);
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
ALTER TABLE content_items ENABLE ROW LEVEL SECURITY; ALTER TABLE content_items FORCE ROW LEVEL SECURITY;
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY memberships_workspace_isolation ON memberships USING (workspace_id = nullif(current_setting('app.current_workspace_id',true),'')::uuid) WITH CHECK (workspace_id = nullif(current_setting('app.current_workspace_id',true),'')::uuid);
CREATE POLICY content_workspace_isolation ON content_items USING (workspace_id = nullif(current_setting('app.current_workspace_id',true),'')::uuid) WITH CHECK (workspace_id = nullif(current_setting('app.current_workspace_id',true),'')::uuid);
CREATE POLICY audit_workspace_isolation ON audit_events USING (workspace_id = nullif(current_setting('app.current_workspace_id',true),'')::uuid) WITH CHECK (workspace_id = nullif(current_setting('app.current_workspace_id',true),'')::uuid);
-- Runtime DATABASE_URL must use a dedicated non-superuser, non-table-owner role without BYPASSRLS.
